/**
 * Abstract base class for all plugins.
 *
 * All plugin implementations must extend this class. It defines the required contract for
 * plugin metadata, settings management, and provides a hook (`onConfigure`) for handling
 * configuration changes.
 *
 * @property static __module - The module name this plugin belongs to. Used for grouping and identification.
 * @property settings - Current settings applied to the plugin.
 *
 * @method configure - Sets plugin settings and triggers `onConfigure` hook.
 * @method onConfigure - Optional lifecycle hook called after configuration changes. Can be overridden by plugins.
 */
export class PluginBase {
    static __module = "core";
    settings = {};
    /**
     * Updates the plugin settings and triggers the configuration hook.
     * @param settings - New settings to apply to the plugin.
     */
    configure(settings) {
        this.settings = settings;
        this.onConfigure(settings);
    }
    /**
     * Lifecycle hook called after `configure()` is invoked.
     * Plugins can override this method to react to configuration changes.
     * @param _settings - The settings passed to `configure()`.
     */
    // eslint-disable-next-line @typescript-eslint/no-unused-vars
    onConfigure(_settings) {
        // This method is intentionally left blank for subclasses to override.
    }
}
